(()=>{const names=["webkitAnimation", "webkitBorderAfter", "webkitBorderBefore", "webkitBorderEnd", "webkitBorderRadius", "webkitBorderStart", "webkitColumnRule", "webkitColumns", "webkitFlex", "webkitFlexFlow", "webkitMask", "webkitMaskBoxImage", "webkitMaskPosition", "webkitTextEmphasis", "webkitTextStroke", "webkitTransition"];const values=['initial','inherit','none','auto','1px solid red','1 0 auto','row wrap','opacity 1s ease','slide 2s linear','2px','2px 4px','red','circle','var(--value)'];const out={};for(const name of names){out[name]={};for(const value of values){const s=document.createElement('div').style;s[name]=value;out[name][value]={text:s.cssText,value:s[name],components:Array.from({length:s.length},(_,i)=>{const key=s.item(i);return [key,s.getPropertyValue(key)]})};}}return out})()
